IF DB_ID(N'HeritageFameArtGallery') IS NULL CREATE DATABASE [HeritageFameArtGallery];
GO
USE [HeritageFameArtGallery];
GO
IF OBJECT_ID('dbo.AdminUsers','U') IS NULL CREATE TABLE dbo.AdminUsers(AdminId INT IDENTITY(1,1) PRIMARY KEY,Username NVARCHAR(50) NOT NULL UNIQUE,PasswordHash NVARCHAR(100) NOT NULL);
IF OBJECT_ID('dbo.Users','U') IS NULL CREATE TABLE dbo.Users(UserId INT IDENTITY(1,1) PRIMARY KEY,FullName NVARCHAR(100) NOT NULL,Email NVARCHAR(150) NOT NULL UNIQUE,PasswordHash NVARCHAR(100) NOT NULL,Phone NVARCHAR(30) NULL,CreatedAt DATETIME NOT NULL DEFAULT GETDATE(),LastLogin DATETIME NULL);
IF OBJECT_ID('dbo.Artworks','U') IS NULL CREATE TABLE dbo.Artworks(ArtId INT IDENTITY(1,1) PRIMARY KEY,Title NVARCHAR(150) NOT NULL,Artist NVARCHAR(150) NOT NULL,Category NVARCHAR(80) NOT NULL,Medium NVARCHAR(100) NOT NULL,Size NVARCHAR(80) NULL,Price DECIMAL(12,2) NOT NULL,ImageUrl NVARCHAR(1000) NOT NULL,Description NVARCHAR(1000) NULL,CreatedAt DATETIME NOT NULL DEFAULT GETDATE());
IF OBJECT_ID('dbo.Favorites','U') IS NULL CREATE TABLE dbo.Favorites(FavoriteId INT IDENTITY(1,1) PRIMARY KEY,UserId INT NOT NULL,ArtId INT NOT NULL,CreatedAt DATETIME NOT NULL DEFAULT GETDATE(),CONSTRAINT FK_Favorites_Users FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId) ON DELETE CASCADE,CONSTRAINT FK_Favorites_Artworks FOREIGN KEY(ArtId) REFERENCES dbo.Artworks(ArtId) ON DELETE CASCADE,CONSTRAINT UQ_Favorites UNIQUE(UserId,ArtId));
IF OBJECT_ID('dbo.Cart','U') IS NULL CREATE TABLE dbo.Cart(CartId INT IDENTITY(1,1) PRIMARY KEY,UserId INT NOT NULL,ArtId INT NOT NULL,Quantity INT NOT NULL DEFAULT 1,AddedAt DATETIME NOT NULL DEFAULT GETDATE(),CONSTRAINT FK_Cart_Users FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId) ON DELETE CASCADE,CONSTRAINT FK_Cart_Artworks FOREIGN KEY(ArtId) REFERENCES dbo.Artworks(ArtId) ON DELETE CASCADE,CONSTRAINT UQ_Cart UNIQUE(UserId,ArtId));
IF OBJECT_ID('dbo.Orders','U') IS NULL CREATE TABLE dbo.Orders(OrderId INT IDENTITY(1001,1) PRIMARY KEY,UserId INT NOT NULL,OrderDate DATETIME NOT NULL DEFAULT GETDATE(),TotalAmount DECIMAL(12,2) NOT NULL,Status NVARCHAR(40) NOT NULL DEFAULT 'Order Placed',PaymentMethod NVARCHAR(40) NOT NULL,PaymentStatus NVARCHAR(40) NOT NULL DEFAULT 'Pending',TransactionId NVARCHAR(100) NULL,ShippingAddress NVARCHAR(500) NOT NULL,CONSTRAINT FK_Orders_Users FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId));
IF OBJECT_ID('dbo.OrderDetails','U') IS NULL CREATE TABLE dbo.OrderDetails(OrderDetailId INT IDENTITY(1,1) PRIMARY KEY,OrderId INT NOT NULL,ArtId INT NOT NULL,Title NVARCHAR(150) NOT NULL,Price DECIMAL(12,2) NOT NULL,Quantity INT NOT NULL,CONSTRAINT FK_OrderDetails_Orders FOREIGN KEY(OrderId) REFERENCES dbo.Orders(OrderId) ON DELETE CASCADE,CONSTRAINT FK_OrderDetails_Artworks FOREIGN KEY(ArtId) REFERENCES dbo.Artworks(ArtId));
IF OBJECT_ID('dbo.OrderTracking','U') IS NULL CREATE TABLE dbo.OrderTracking(TrackingId INT IDENTITY(1,1) PRIMARY KEY,OrderId INT NOT NULL,Status NVARCHAR(40) NOT NULL,Note NVARCHAR(300) NULL,UpdatedAt DATETIME NOT NULL DEFAULT GETDATE(),CONSTRAINT FK_OrderTracking_Orders FOREIGN KEY(OrderId) REFERENCES dbo.Orders(OrderId) ON DELETE CASCADE);
IF OBJECT_ID('dbo.ActivityLog','U') IS NULL CREATE TABLE dbo.ActivityLog(LogId INT IDENTITY(1,1) PRIMARY KEY,UserId INT NULL,AdminId INT NULL,Action NVARCHAR(100) NOT NULL,Details NVARCHAR(500) NULL,CreatedAt DATETIME NOT NULL DEFAULT GETDATE());
IF NOT EXISTS(SELECT 1 FROM AdminUsers WHERE Username='admin') INSERT INTO AdminUsers(Username,PasswordHash) VALUES('admin','admin123');
GO

